export type DivisionSpecRow = { label: string; value: string };

export type DivisionRoute = { label: string; href: string; external?: boolean };

export type DivisionProofMetric = { key: string; name: string; value: string };

export type Division = {
  index: string;
  title: string;
  writeup: string;
  spec: readonly DivisionSpecRow[];
  proof: string;
  proofSource: string;
  route: DivisionRoute;
  source: string;
  anchor?: string;
  metrics: readonly DivisionProofMetric[];
};

/**
 * Proof-metric references per vertical, keyed by vertical index. Each key
 * resolves against the published Metrics ledger (§11.3); the figure lives once
 * in the ledger and the vertical references it rather than duplicating it.
 * The `metrics` field on the CMS `business-verticals` records is seeded from
 * this index and the parity layer verifies the two stay in step.
 */
export const VERTICAL_PROOF_METRIC_KEYS: Readonly<Record<string, readonly string[]>> = {
  "01": ["M14"],
  "02": [],
  "03": [],
};

type CmsVerticalRecord = {
  id: string;
  index: string;
  title: string;
  writeup: string;
  proof: string;
  proofSource: string;
  anchor?: string;
  source: string;
  spec: readonly { label: string; value: string }[];
  route: { label: string; href: string; external?: boolean };
  metrics: readonly { metricKey?: string }[];
};

const cmsVerticalData = cmsVerticals as unknown as readonly CmsVerticalRecord[];

const cmsDivisions: readonly Division[] = cmsVerticalData.map((record) => ({
  index: record.index,
  title: record.title,
  writeup: record.writeup,
  spec: record.spec.map((row) => ({ label: row.label, value: row.value })),
  proof: record.proof,
  proofSource: record.proofSource,
  ...(record.anchor !== undefined ? { anchor: record.anchor } : {}),
  route: {
    label: record.route.label,
    href: record.route.href,
    ...(record.route.external === true ? { external: true } : {}),
  },
  source: record.source,
  metrics: record.metrics
    .map(({ metricKey }) => cmsMetrics.find((metric) => metric.key === metricKey))
    .filter((metric): metric is (typeof cmsMetrics)[number] => metric !== undefined)
    .map((metric) => ({ key: metric.key, name: metric.name, value: metric.value })),
}));

export const divisions: readonly Division[] = cmsDivisions;

